APP="EVE Escalation Watcher"
BASE="https://www.fuzzwork.co.uk/dump/latest/csv/"
LINE=re.compile(r"^\ufeff?\[\s*(?P<time>[^\]]+)\s*\]\s+(?P<author>.*?)\s*>\s*(?P<text>.*)$")
TOKEN=re.compile(r"(?<![A-Z0-9-])([A-Z0-9]{1,6}-[A-Z0-9]{1,6})(?![A-Z0-9-])",re.I)
# Exactly the filename format generated by EVE for this one channel.
CHAT_FILE=re.compile(r"^Imperium Expeditions_(?P<date>\d{8})_(?P<time>\d{6})_(?P<id>\d+)\.txt$",re.IGNORECASE)
BRIDGE=re.compile(r"^\s*([A-Z0-9-]{1,20})\s*->\s*([A-Z0-9-]{1,20})\s*$",re.IGNORECASE)
BUY_MARKER=re.compile(r" [xх](?: |[.,]?$)",re.IGNORECASE)
