def parse_bridges(text):
 pairs=[]
 for line in text.splitlines():
  m=BRIDGE.match(line)
  if m and m[1].upper()!=m[2].upper():pairs.append((m[1].upper(),m[2].upper()))
 return sorted(set(tuple(sorted(x)) for x in pairs))
def resource_path(name):
 return Path(getattr(sys,"_MEIPASS",Path(__file__).parent))/name
def data_dir():
 p=(Path(sys.executable).parent if getattr(sys,"frozen",False) else Path(__file__).parent)/"eve_watcher_data";p.mkdir(exist_ok=True);return p
def default_sound_file(saved_sound_file=""):
 # A user's saved choice always wins; new installations use the bundled alert.
 return saved_sound_file or str(data_dir()/"alert1.mp3")
class Universe:
 def __init__(s):s.names={};s.graph={}
 @property
 def ready(s):return bool(s.names and s.graph)
 def load(s):
  p=data_dir()/"universe.json"
  if not p.exists():return False
  d=json.loads(p.read_text(encoding="utf-8"));s.names=d["names"];s.graph={k:set(v) for k,v in d["graph"].items()};return s.ready
 def update(s):
  get=lambda n:urllib.request.urlopen(BASE+n,timeout=45).read().decode("utf-8-sig")
  ids={r["solarSystemID"]:r["solarSystemName"] for r in csv.DictReader(get("mapSolarSystems.csv").splitlines())}
  g={x.upper():set() for x in ids.values()}
  for r in csv.DictReader(get("mapSolarSystemJumps.csv").splitlines()):
   a,b=ids.get(r["fromSolarSystemID"]),ids.get(r["toSolarSystemID"])
   if a and b:g[a.upper()].add(b.upper());g[b.upper()].add(a.upper())
  s.names={x.upper():x for x in ids.values()};s.graph=g
  (data_dir()/"universe.json").write_text(json.dumps({"names":s.names,"graph":{k:sorted(v) for k,v in g.items()}}),encoding="utf-8")
 def nearby(s,origin,limit,bridges=()):
  origin=origin.strip().upper()
  if origin not in s.names:raise ValueError("Систему не знайдено в каталозі EVE.")
  extra={}
  for a,b in bridges:
   extra.setdefault(a,set()).add(b);extra.setdefault(b,set()).add(a)
  out,q={origin:0},deque([origin])
  while q:
   x=q.popleft()
   if out[x]>=limit:continue
   for y in s.graph.get(x,())|extra.get(x,set()):
    if y not in out:out[y]=out[x]+1;q.append(y)
  return out
def parse_chat_line(line):
 m=LINE.match(line.strip())
 if not m:return None
 return (m["time"].strip(),m["author"].strip(),m["text"].strip())
def parse(line,nearby):
 item=parse_chat_line(line)
 if not item:return []
 stamp,author,text=item;offers=[];seen=set()
 # A purchase marker is valid only immediately after this exact system token:
 # ASCII space, x/х (any case), then a space, end, period, or comma.
 for match in TOKEN.finditer(text):
  system=match.group(1).upper()
  if system in nearby and system not in seen and not BUY_MARKER.match(text,match.end()):
   offers.append((stamp,author,system,nearby[system],text));seen.add(system)
 return offers
def is_expeditions_log(path):
 try:
  # Filename and the in-file channel header must both identify this exact chat.
  return "Channel Name:    Imperium Expeditions" in path.read_text(encoding="utf-16",errors="replace")[:1500]
 except OSError:return False
def newest_chat_file(folder):
 folder=Path(folder);candidates=[]
 for p in folder.iterdir():
  match=CHAT_FILE.fullmatch(p.name) if p.is_file() else None
  if match and is_expeditions_log(p):candidates.append((match["date"],match["time"],match["id"],p))
 return max(candidates,key=lambda x:x[:3])[3] if candidates else None

