 def edit_bridges(s):
  w=tk.Toplevel(s);w.title(s.t("bridges_title"));w.geometry("570x520");w.transient(s);w.grab_set()
  ttk.Label(w,text=s.t("bridges_help"),justify="left").pack(anchor="w",padx=10,pady=10)
