 def paste_home(s,event):
  # keycode 86 is the physical V key in Windows, including Russian keyboard layout.
  if event.keycode!=86:return None
  try:
   s.box.delete("sel.first","sel.last")
  except tk.TclError:pass
  try:s.box.insert("insert",s.clipboard_get())
  except tk.TclError:return "break"
