 def play_alert(s):
  p=Path(s.sound_file.get())
  if p.is_file():
   try:
    q=lambda text: '"'+str(text).replace('"','')+'"'
    ctypes.windll.winmm.mciSendStringW(f"close {s.sound_alias}",None,0,None)
    device="mpegvideo" if p.suffix.lower()==".mp3" else "waveaudio"
    if ctypes.windll.winmm.mciSendStringW(f"open {q(p)} type {device} alias {s.sound_alias}",None,0,None)==0:
     ctypes.windll.winmm.mciSendStringW(f"setaudio {s.sound_alias} volume to {s.volume.get()*10}",None,0,None)
     ctypes.windll.winmm.mciSendStringW(f"play {s.sound_alias} from 0",None,0,None);return
   except (AttributeError,OSError):pass
  try:winsound.MessageBeep(winsound.MB_ICONEXCLAMATION)
  except RuntimeError:s.bell()
